-- DMT_05: Helenz receipts imported before the importer kept the old system's numbers.
-- The old app printed "INV-<payment id, 8 digits>" (invoice_prefix = INV) on member payments and no
-- number on day passes; LegacyGymTransformer now gives imported receipts those numbers (day passes
-- DP-<old day-pass id>) as both receipt and invoice number. Receipts created in the app afterwards keep
-- RCPT-/INV-YYYY- numbering. Run against the tenant DB (e.g. gymbios_helenz). Safe to re-run.
--
-- The map below is the importer's output for helenzdata.sql (receipt id → number). A row is only
-- renumbered if its member, amount, type and date still match that import, so another gym's DB is
-- left alone. Also renames the number in receipt_vouchers (reference/transaction_id) and journal
-- voucher narrations; financial_audit_logs keep what was logged at import time.
BEGIN;

CREATE TEMP TABLE receipt_number_map (id bigint, new_no text, is_invoice boolean, member_id text,
    amount numeric, transaction_type text, transaction_date timestamp) ON COMMIT DROP;
