CREATE TEMP TABLE receipt_renumber ON COMMIT DROP AS
SELECT r.id, r.receipt_no AS old_no, m.new_no, m.is_invoice
FROM receipts r JOIN receipt_number_map m ON m.id = r.id
WHERE r.created_by = 'legacy-import' AND r.receipt_no <> m.new_no
  AND r.member_id IS NOT DISTINCT FROM m.member_id AND r.amount = m.amount
  AND r.transaction_type = m.transaction_type AND r.transaction_date = m.transaction_date;

UPDATE receipt_vouchers v SET reference = x.new_no
FROM receipt_renumber x WHERE v.reference = x.old_no;
UPDATE receipt_vouchers v SET transaction_id = x.new_no
FROM receipt_renumber x WHERE v.transaction_id = x.old_no;
UPDATE journal_vouchers j SET narration = replace(j.narration, x.old_no, x.new_no)
FROM receipt_renumber x
WHERE j.narration LIKE '%RCPT-%' AND substring(j.narration FROM 'RCPT-[0-9]{10}') = x.old_no;
UPDATE receipts r SET receipt_no = x.new_no,
    invoice_no = CASE WHEN x.is_invoice THEN x.new_no ELSE r.invoice_no END
FROM receipt_renumber x WHERE r.id = x.id;

SELECT (SELECT count(*) FROM receipt_renumber) AS renumbered,
       (SELECT count(*) FROM receipts WHERE receipt_no LIKE 'INV-%') AS inv_numbers,
       (SELECT count(*) FROM receipts WHERE receipt_no LIKE 'DP-%') AS day_pass_numbers,
       (SELECT count(*) FROM receipts WHERE receipt_no LIKE 'RCPT-%') AS still_rcpt;

COMMIT;
